macro_rules! refused_carriers {
    () => {
        Carrier::Quic
            | Carrier::Kcp(_)
            | Carrier::Hysteria(_)
            | Carrier::Masque
            | Carrier::Xdrive { .. }
            | Carrier::Http
            | Carrier::Unknown { .. }
    };
}

