        let target: SocketAddr = "127.0.0.1:53".parse().expect("addr");
        let mut header = vec![0u8];
        header.extend_from_slice(&id);
        header.push(18);
        header.extend_from_slice(b"\x0A\x10xtls-rprx-vision");
